/* global module, require */
(function (root, factory) {
  "use strict";
  const shared = root?.KB_DIVIDEND_COMMON_ROWS || (typeof module === "object" && module.exports ? require("./dividend-locale-common") : []);
  const api = factory(shared);
  if (typeof module === "object" && module.exports) module.exports = api;
  if (!root?.document || new URLSearchParams(root.location.search).has("__kb_static_export")) return;
  const doc = root.document;
  const main = doc.querySelector("main.page-osztalek");
  if (!main) return;
  const textRecords = new WeakMap();
  const attributeRecords = new WeakMap();
  let language = root.KB_SITE_LANGUAGE?.get() || "hu";
  let observer;
  const excluded = 'script,style,textarea,pre,code,input,[contenteditable],[translate="no"]';
  function render() {
    observer?.disconnect();
    try {
      const walker = doc.createTreeWalker(main, NodeFilter.SHOW_TEXT);
      while (walker.nextNode()) {
        const node = walker.currentNode;
        if (node.parentElement?.closest(excluded)) continue;
        const previous = textRecords.get(node);
        const source = previous?.rendered === node.nodeValue ? previous.source : node.nodeValue;
        const match = /^(\s*)([\s\S]*?)(\s*)$/u.exec(source);
        if (!match?.[2]) continue;
        const option = node.parentElement?.closest("option:not([value])");
        if (option && !option.hasAttribute("data-kb-locale-value")) {
          option.value = option.textContent.trim();
          option.setAttribute("data-kb-locale-value", "true");
        }
        const translated = api.translate("osztalek-kalkulator", match[2].replace(/\s+/gu, " ").trim(), language);
        const rendered = match[1] + (translated ?? match[2]) + match[3];
        if (node.nodeValue !== rendered) node.nodeValue = rendered;
        textRecords.set(node, { source, rendered });
      }
      main.querySelectorAll("[aria-label],[placeholder],[title]").forEach(element => {
        if (element.closest('select,textarea,pre,code,[contenteditable],[translate="no"]')) return;
        for (const name of ["aria-label", "placeholder", "title"]) {
          if (!element.hasAttribute(name)) continue;
          let records = attributeRecords.get(element);
          if (!records) { records = new Map(); attributeRecords.set(element, records); }
          const current = element.getAttribute(name);
          const previous = records.get(name);
          const source = previous?.rendered === current ? previous.source : current;
          const rendered = api.translate("osztalek-kalkulator", source.replace(/\s+/gu, " ").trim(), language) ?? source;
          if (current !== rendered) element.setAttribute(name, rendered);
          records.set(name, { source, rendered });
        }
      });
    } finally { observer?.observe(main, { subtree: true, childList: true, characterData: true }); }
  }
  root.KB_DIVIDEND_LOCALE = Object.freeze({ translateText: value => api.translate("osztalek-kalkulator", String(value), language), getLanguage: () => language });
  doc.addEventListener("kb:language-changed", event => {
    language = api.supported.includes(event.detail?.language) ? event.detail.language : "hu";
    render();
  });
  const ready = () => { observer = new MutationObserver(render); render(); };
  if (doc.readyState === "loading") doc.addEventListener("DOMContentLoaded", ready, { once: true }); else ready();
})(typeof window === "undefined" ? null : window, function (commonRows) {
  "use strict";
  const ownRows = [
    [", különösen az osztalékból származó jövedelemre vonatkozó rendelkezések, valamint a", ", particularly the provisions on income from dividends, as well as", ", insbesondere die Bestimmungen zu Einkünften aus Dividenden sowie"],
    [". A kalkulátor nem feltételez automatikusan minden élethelyzetre érvényes adómértéket: a levonásokat a felhasználó által megadott adatokkal modellezi.", ". The calculator does not assume a tax rate that applies to every situation; it models deductions using the information you provide.", ". Der Rechner unterstellt keinen Steuersatz, der für alle Situationen gilt, sondern modelliert Abzüge anhand deiner Angaben."],
    ["1 és 60 év közötti időtávval érdemes becsülni.", "Use a time horizon between 1 and 60 years.", "Schätze mit einem Zeitraum zwischen 1 und 60 Jahren."],
    ["A bruttó osztalék a levonások előtti összeg. A nettó osztalék az, amely a megadott becsült adók és költségek után megmaradhat. A kalkulátor nem alkalmaz automatikusan aktuális adójogi szabályokat, mert a tényleges kezelés függhet az országtól, a számlatípustól, az értékpapírtól, a forrásadótól és az egyéni körülményektől.", "Gross dividends are the amount before deductions. Net dividends are what may remain after the estimated taxes and costs you enter. The calculator does not apply current tax rules automatically because treatment may depend on country, account type, security, withholding tax and personal circumstances.", "Bruttodividenden sind Beträge vor Abzügen. Nettodividenden sind der Betrag, der nach den von dir geschätzten Steuern und Kosten verbleiben könnte. Der Rechner wendet keine aktuellen Steuervorschriften automatisch an, da die Behandlung von Land, Kontotyp, Wertpapier, Quellensteuer und persönlichen Umständen abhängen kann."],
    ["A bruttó osztalékból becsült elsődleges levonás.", "Estimated primary deduction from gross dividends.", "Geschätzter Hauptabzug von der Bruttodividende."],
    ["A céljövedelem mód visszaszámolja, hogy a megadott bruttó osztalékhozam és becsült levonások mellett mekkora portfólióra lehet szükség. Nettó cél esetén a kalkulátor a fix éves költséget is hozzáadja a célhoz, majd felfelé kerekített tőkével újraszámol, hogy a becsült nettó osztalék legalább elérje a célt.", "Target-income mode estimates the portfolio size needed at the gross dividend yield and deductions you enter. For a net target, it also adds annual fixed costs and recalculates using rounded-up capital so estimated net dividends reach the target.", "Der Zielmodus schätzt die erforderliche Portfoliogröße anhand der eingegebenen Bruttodividendenrendite und Abzüge. Bei einem Nettoziel addiert er die jährlichen Fixkosten und rechnet mit aufgerundetem Kapital erneut, damit die geschätzte Nettodividende mindestens das Ziel erreicht."],
    ["A forgatókönyvek nem hozam- vagy osztalékígéretek. Eltérő feltételezéseken alapuló becslések.", "The scenarios are not promises of returns or dividends; they are estimates based on different assumptions.", "Die Szenarien sind keine Zusagen für Rendite oder Dividenden, sondern Schätzungen auf Basis unterschiedlicher Annahmen."],
    ["A grafikon az osztalékbevétel, a portfólióérték vagy a szükséges tőke becsült alakulását mutatja.", "The chart estimates how dividend income, portfolio value or required capital may change over time.", "Das Diagramm schätzt die Entwicklung der Dividendeneinnahmen, des Portfoliowerts oder des erforderlichen Kapitals."],
    ["A hosszú távú modell külön kezeli az egységárat, az egységenkénti osztalékot, a rendszeres vásárlásokat és az újrabefektetést. Az infláció nem újabb levonás: azt becsüli, hogy a jövőbeni forintösszeg mai vásárlóértéken körülbelül mennyit érhet.", "The long-term model treats unit price, dividends per unit, regular purchases and reinvestment separately. Inflation is not an extra deduction; it estimates what a future HUF amount might be worth in today's purchasing power.", "Das Langzeitmodell berücksichtigt Anteilspreis, Dividende je Anteil, regelmäßige Käufe und Wiederanlage getrennt. Inflation ist kein zusätzlicher Abzug, sondern schätzt den Wert eines künftigen HUF-Betrags in heutiger Kaufkraft."],
    ["A hónap végén befektetett összeg, amely a következő időszaktól termelhet osztalékot.", "The amount invested at the end of each month, which may start generating dividends in the following period.", "Der am Monatsende angelegte Betrag, der ab der nächsten Periode Dividenden erwirtschaften kann."],
    ["A kalkulátor a megadott feltételek alapján készít matematikai becslést. Nem végez automatikus adójogi minősítést, ezért az adó- és levonási arányokat saját becslésként add meg.", "The calculator provides a mathematical estimate based on your assumptions. It does not determine your tax status, so enter your own estimated tax and deduction rates.", "Der Rechner erstellt anhand deiner Angaben eine mathematische Schätzung. Er nimmt keine automatische steuerliche Einordnung vor. Gib daher eigene Schätzwerte für Steuern und Abzüge ein."],
    ["A kalkulátor eredménye becslés, nem minősül befektetési, adózási vagy pénzügyi tanácsadásnak. Az osztalék nem garantált, a vállalat csökkentheti vagy megszüntetheti. Az árfolyam, az adózás, a forrásadó, a devizaárfolyam és a költségek miatt a tényleges eredmény eltérhet a számított értéktől.", "The result is an estimate, not investment, tax or financial advice. Dividends are not guaranteed and a company may reduce or stop them. Actual results may differ because of share prices, taxes, withholding tax, exchange rates and costs.", "Das Ergebnis ist eine Schätzung und keine Anlage-, Steuer- oder Finanzberatung. Dividenden sind nicht garantiert und können gekürzt oder eingestellt werden. Kurse, Steuern, Quellensteuer, Wechselkurse und Kosten können zu abweichenden Ergebnissen führen."],
    ["A kiugró osztalékhozam lehet árfolyamesés vagy várható osztalékvágás következménye is. A magas százalék önmagában nem minőségi jel.", "An unusually high dividend yield may result from a falling share price or an expected dividend cut. A high percentage alone is not a quality signal.", "Eine ungewöhnlich hohe Dividendenrendite kann auf einen fallenden Kurs oder eine erwartete Dividendenkürzung zurückgehen. Ein hoher Prozentsatz allein ist kein Qualitätsmerkmal."],
    ["A magas osztalékhozam elsőre vonzó, de nem feltétlenül jelent jó befektetést. Gyakran előfordul, hogy a hozam azért magas, mert az árfolyam jelentősen esett, a piac osztalékvágást áraz, vagy a kifizetés hosszú távon nem fenntartható. Osztaléktervezéskor érdemes a vállalat minőségét, adósságát, nyereségességét és diverzifikációját is figyelni.", "A high dividend yield may look attractive, but it does not necessarily signal a good investment. It can be high because the share price has fallen, the market expects a dividend cut, or the payout is unsustainable. Consider the company's quality, debt, profitability and diversification as well.", "Eine hohe Dividendenrendite wirkt zunächst attraktiv, ist aber nicht unbedingt ein Zeichen für eine gute Anlage. Sie kann auf einen stark gefallenen Kurs, eine erwartete Dividendenkürzung oder eine nicht tragfähige Ausschüttung zurückgehen. Achte auch auf Qualität, Verschuldung, Rentabilität und Diversifikation des Unternehmens."],
    ["A részvények és ETF-ek fizethetnek havonta, negyedévente, félévente vagy évente. A kalkulátor havi nettó átlagot is mutat, de ez nem jelenti azt, hogy minden hónapban ugyanakkora összeg érkezik. A havi érték inkább tervezési átlag, amely segíthet a céljövedelem nagyságrendjének megértésében.", "Stocks and ETFs may pay monthly, quarterly, semi-annually or annually. The calculator also shows average monthly net income, but payments will not necessarily arrive in equal amounts every month. Treat the monthly figure as a planning average.", "Aktien und ETFs können monatlich, vierteljährlich, halbjährlich oder jährlich ausschütten. Der Rechner zeigt auch einen monatlichen Nettodurchschnitt. Das bedeutet jedoch nicht, dass jeden Monat dieselbe Summe eingeht. Der Monatswert ist ein Planungsdurchschnitt."],
    ["A tervezésnél három külön kérdést érdemes szétválasztani: mennyi a vállalat vagy alap által fizetett bruttó osztalék, ebből mennyi marad levonások után, és mikor érkezik ténylegesen a pénz. A negyedéves vagy éves kifizetésből számolt havi átlag nem egyenletes havi fizetés.", "Separate three questions when planning: how much gross dividend a company or fund pays, how much remains after deductions, and when the money actually arrives. A monthly average based on quarterly or annual payments is not a regular monthly payment.", "Bei der Planung solltest du drei Fragen trennen: Wie hoch ist die Bruttodividende eines Unternehmens oder Fonds, wie viel bleibt nach Abzügen übrig und wann geht das Geld tatsächlich ein? Ein Monatsdurchschnitt aus vierteljährlichen oder jährlichen Zahlungen ist keine gleichmäßige Monatszahlung."],
    ["A tényleges nettó kifizetés ország, értékpapír, számlatípus és egyezmények szerint eltérhet. Ezért a kalkulátor a levonást felhasználói feltételezésként kezeli.", "Actual net payments can vary by country, security, account type and tax treaties. The calculator therefore treats deductions as a user assumption.", "Die tatsächliche Nettozahlung kann je nach Land, Wertpapier, Kontotyp und Steuerabkommen variieren. Deshalb behandelt der Rechner Abzüge als Benutzerschätzung."],
    ["A „havi osztalék” többnyire csak éves átlag", "“Monthly dividends” are usually just an annual average", "„Monatliche Dividenden“ sind meist nur ein Jahresdurchschnitt"],
    ["Add meg, mekkora havi vagy éves osztalékbevételt szeretnél becsülni.", "Enter the monthly or annual dividend income you want to estimate.", "Gib an, welche monatlichen oder jährlichen Dividendeneinnahmen du schätzen möchtest."],
    ["Adott évi saját befizetés", "Contribution in the given year", "Einzahlung im jeweiligen Jahr"], ["Adó és forrásadó", "Tax and withholding tax", "Steuer und Quellensteuer"], ["Az adott év elején egyszeri vágást alkalmazunk.", "A one-time cut is applied at the start of the selected year.", "Zu Beginn des ausgewählten Jahres wird eine einmalige Kürzung angewendet."],
    ["Az adózás minden befektetésnél ugyanaz?", "Is taxation the same for every investment?", "Ist die Besteuerung bei jeder Anlage gleich?"], ["Az aktuális osztaléktermelő portfólió becsült értéke.", "Estimated value of your current dividend-paying portfolio.", "Geschätzter Wert deines aktuellen Dividendenportfolios."], ["Az egy egységre jutó osztalék feltételezett éves változása.", "Assumed annual change in the dividend per share or unit.", "Angenommene jährliche Veränderung der Dividende je Anteil."],
    ["Az infláció csökkentheti a jövőbeni osztalék vásárlóerejét, ezért a kalkulátor külön mai vásárlóértéket is mutat.", "Inflation can reduce the future purchasing power of dividends, so the calculator also shows an estimate in today's money.", "Inflation kann die künftige Kaufkraft von Dividenden mindern. Deshalb zeigt der Rechner zusätzlich eine Schätzung in heutiger Kaufkraft."],
    ["Az osztalék a vállalat nyereségéből vagy felhalmozott eredményéből kifizetett összeg, amelyet a részvényesek a tulajdoni arányuk alapján kaphatnak. Nem automatikus és nem garantált: a vállalat vezetése és közgyűlése dönthet úgy, hogy csökkenti, felfüggeszti vagy teljesen megszünteti a kifizetést.", "A dividend is a payment from a company's profit or retained earnings that shareholders may receive in proportion to their ownership. It is neither automatic nor guaranteed: management and shareholders may decide to reduce, suspend or stop payments entirely.", "Eine Dividende ist eine Zahlung aus Gewinn oder einbehaltenen Ergebnissen, die Aktionäre entsprechend ihrem Anteil erhalten können. Sie ist weder automatisch noch garantiert: Unternehmensleitung und Hauptversammlung können die Zahlung kürzen, aussetzen oder einstellen."],
    ["Az osztalék csak az egyik komponens. Árfolyamnyereség, veszteség, deviza és költség együtt adja a befektetés tényleges eredményét.", "Dividends are only one component. Capital gains or losses, currency movements and costs together determine an investment's actual result.", "Dividenden sind nur ein Bestandteil. Kursgewinne oder -verluste, Währungsbewegungen und Kosten bestimmen gemeinsam das tatsächliche Anlageergebnis."],
    ["Az osztalék és a teljes hozam nem ugyanaz. Egy befektetés hozama jöhet osztalékból, árfolyamnyereségből vagy veszteségből, devizahatásból és költségek változásából. A kalkulátor hasznos tervezési segédlet, de nem helyettesíti az egyedi adózási vagy befektetési döntést.", "Dividends and total return are not the same. Investment returns can include dividends, capital gains or losses, currency effects and changing costs. This calculator is a planning aid, not a substitute for individual tax or investment decisions.", "Dividenden und Gesamtrendite sind nicht dasselbe. Anlageerträge können aus Dividenden, Kursgewinnen oder -verlusten, Währungseffekten und veränderten Kosten entstehen. Dieser Rechner ist eine Planungshilfe und ersetzt keine individuelle Steuer- oder Anlageentscheidung."],
    ["Az osztalékhozam azt mutatja meg, hogy az éves bruttó osztalék a befektetett összeg hány százaléka. Ha egy 3 millió forintos portfólió 4% bruttó osztalékhozammal számolható, akkor az éves bruttó osztalék becslés szerint 120 000 Ft. A nettó összeg ettől eltérhet az adók, levonások, devizaváltás és egyéb költségek miatt.", "Dividend yield shows annual gross dividends as a percentage of the invested amount. At a 4% gross yield, a HUF 3 million portfolio would generate an estimated HUF 120,000 in gross annual dividends. Taxes, deductions, currency conversion and other costs may change the net amount.", "Die Dividendenrendite zeigt die jährliche Bruttodividende als Anteil des Anlagebetrags. Bei 4 % Bruttorendite würde ein Portfolio von 3 Mio. HUF voraussichtlich 120.000 HUF jährliche Bruttodividenden erzielen. Steuern, Abzüge, Währungsumtausch und weitere Kosten können den Nettobetrag verändern."],
    ["Az osztalékot kiveszem", "Withdraw the dividends", "Dividenden entnehmen"], ["Az osztalékot újrabefektetem", "Reinvest the dividends", "Dividenden wieder anlegen"], ["Az éves bruttó osztalék és a befektetett összeg arányát mutatja százalékban.", "It shows annual gross dividends as a percentage of the invested amount.", "Sie zeigt die jährliche Bruttodividende als Prozentsatz des Anlagebetrags."],
    ["Becslés, nem garancia. A magas hozam gyakran magasabb kockázattal járhat.", "An estimate, not a guarantee. Higher yields can carry higher risks.", "Eine Schätzung, keine Garantie. Höhere Renditen können mit höheren Risiken verbunden sein."],
    ["Becsüld meg a várható éves és havi osztalékbevételedet, számold ki a céljövedelemhez szükséges tőkét, vagy modellezd, hogyan változhat az osztalékod újrabefektetéssel és rendszeres vásárlással.", "Estimate annual and monthly dividend income, calculate the capital needed for a target income, or model how reinvestment and regular contributions may affect your dividends.", "Schätze jährliche und monatliche Dividendeneinnahmen, berechne das nötige Kapital für ein Einkommensziel oder modelliere, wie Wiederanlage und regelmäßige Einzahlungen deine Dividenden beeinflussen könnten."],
    ["Becsült teljes adó és levonás (%)", "Estimated total tax and deductions (%)", "Geschätzte Gesamtsteuer und Abzüge (%)"], ["Befektetett összeg (Ft)", "Invested amount (HUF)", "Anlagebetrag (HUF)"], ["Bruttó cél", "Gross target", "Bruttoziel"], ["Bruttó vagy nettó osztalékkal számoljak?", "Should I use gross or net dividends?", "Soll ich mit Brutto- oder Nettodividenden rechnen?"], ["Bruttó és nettó osztalék", "Gross and net dividends", "Brutto- und Nettodividenden"], ["Cél időszaka", "Target period", "Zielzeitraum"], ["Cél típusa", "Target type", "Zielart"], ["Deviza átváltó", "Currency converter", "Währungsrechner"], ["Effektív havi rátára alakítva hat az egységárra.", "It affects the unit price after conversion to an effective monthly rate.", "Wirkt nach Umrechnung in eine effektive Monatsrate auf den Anteilspreis."], ["Egy kifizetés nettó összege", "Net amount per payment", "Nettobetrag je Auszahlung"], ["Egyszeri osztalékcsökkentés (%)", "One-time dividend cut (%)", "Einmalige Dividendenkürzung (%)"], ["Egyszerű mód: egyetlen százalékban adod meg a várható teljes levonást.", "Simple mode: enter expected total deductions as a single percentage.", "Einfacher Modus: Gib die erwarteten Gesamtabzüge als einen Prozentsatz ein."], ["Egyszerű összesített levonás", "Simple combined deduction", "Einfache Gesamtabzüge"], ["Egyéb, általad becsült százalékos adó vagy levonás.", "Other percentage-based tax or deduction estimated by you.", "Sonstige von dir geschätzte prozentuale Steuer oder Abzüge."],
    ["Ez a hozamtól és a levonásoktól függ. Például 5% bruttó hozam és 15% levonás mellett körülbelül 28,2 millió Ft szükséges a havi 100 000 Ft nettó célhoz.", "It depends on yield and deductions. For example, at a 5% gross yield and 15% deductions, about HUF 28.2 million would be needed for a HUF 100,000 monthly net target.", "Das hängt von Rendite und Abzügen ab. Bei 5 % Bruttorendite und 15 % Abzügen wären etwa 28,2 Mio. HUF für ein monatliches Nettoziel von 100.000 HUF nötig."], ["Ez egyszerű matematikai becslés. A tényleges adókötelezettség, adóbeszámítás, forrásadó és számlatípus szerinti kezelés eltérhet.", "This is a simple mathematical estimate. Actual tax liability, foreign tax credits, withholding tax and account-specific treatment may differ.", "Dies ist eine einfache mathematische Schätzung. Tatsächliche Steuerschuld, Steueranrechnung, Quellensteuer und Behandlung je nach Kontotyp können abweichen."], ["Forrásadó vagy külföldi levonás (%)", "Withholding tax or foreign deduction (%)", "Quellensteuer oder ausländischer Abzug (%)"], ["Féléves", "Semi-annual", "Halbjährlich"], ["Garantált az osztalék?", "Are dividends guaranteed?", "Sind Dividenden garantiert?"], ["Grafikon típusa", "Chart type", "Diagrammtyp"], ["Gyakori kérdések osztaléktervezés előtt", "Frequently asked questions about dividend planning", "Häufige Fragen zur Dividendenplanung"],
    ["Ha az osztalékot újrabefekteted, akkor a nettó kifizetésből további egységeket vásárolsz. Ezek később maguk is osztalékot termelhetnek. Hosszú idő alatt ez látványos különbséget okozhat, de a valós eredményt árfolyam, adózás, deviza és piaci kockázat is módosíthatja.", "If you reinvest dividends, you use the net payment to buy more shares or units, which may generate dividends later. This can make a difference over time, though prices, taxes, currency movements and market risk also affect actual results.", "Bei einer Wiederanlage kaufst du mit der Nettodividende weitere Anteile, die später selbst Dividenden erwirtschaften können. Über längere Zeit kann das einen Unterschied machen; tatsächliche Ergebnisse hängen auch von Kursen, Steuern, Währungen und Marktrisiken ab."],
    ["Használd stressztesztre, ne ígéretre", "Use it for stress tests, not promises", "Für Stresstests nutzen, nicht als Versprechen"], ["Havi cél", "Monthly target", "Monatsziel"], ["Havi nettó átlag", "Average monthly net income", "Durchschnittliche monatliche Nettoeinnahmen"], ["Hogyan hat az infláció az osztalékjövedelemre?", "How does inflation affect dividend income?", "Wie wirkt sich die Inflation auf Dividendeneinnahmen aus?"], ["Hogyan nőhet az osztalékbevételem?", "How could my dividend income grow?", "Wie könnten meine Dividendeneinnahmen wachsen?"], ["Hosszú távon növelheti a portfóliót és a későbbi osztalékot, de a döntés függhet a kockázattűréstől és a céloktól.", "It may grow the portfolio and future dividends over the long term, but the choice depends on your risk tolerance and goals.", "Langfristig kann es Portfolio und spätere Dividenden erhöhen. Die Entscheidung hängt jedoch von Risikobereitschaft und Zielen ab."], ["Hozamcsapda", "Yield trap", "Renditefalle"], ["Három óvatosan értelmezendő feltételezés", "Three assumptions to interpret with care", "Drei Annahmen, die vorsichtig zu bewerten sind"], ["Kezdő portfólió (Ft)", "Starting portfolio (HUF)", "Startportfolio (HUF)"], ["Kifizetési gyakoriság", "Payout frequency", "Auszahlungshäufigkeit"], ["Kifizetési gyakoriság és havi átlag", "Payout frequency and monthly average", "Auszahlungshäufigkeit und Monatsdurchschnitt"], ["Kifizetési vagy devizaváltási költség (%)", "Payout or currency-conversion fee (%)", "Auszahlungs- oder Währungsumtauschgebühr (%)"], ["Kivett osztalék", "Withdrawn dividends", "Entnommene Dividenden"], ["Kívánt osztalékjövedelem (Ft)", "Target dividend income (HUF)", "Gewünschte Dividendeneinnahmen (HUF)"], ["Következő évi nettó osztalék", "Next year's net dividends", "Nettodividende im Folgejahr"], ["Levonási mód", "Deduction method", "Abzugsmethode"], ["Mai vásárlóértékű portfólió", "Portfolio in today's money", "Portfoliowert in heutiger Kaufkraft"], ["Mekkora portfólió kell havi 100 000 Ft osztalékhoz?", "What portfolio size is needed for HUF 100,000 in monthly dividends?", "Wie groß muss ein Portfolio für 100.000 HUF monatliche Dividenden sein?"], ["Mekkora tőke kell egy választott céljövedelemhez?", "How much capital is needed for a chosen income target?", "Wie viel Kapital ist für ein gewähltes Einkommensziel nötig?"], ["Mekkora tőke kell?", "How much capital do I need?", "Wie viel Kapital brauche ich?"], ["Melyik évben történik?", "In which year does it happen?", "In welchem Jahr erfolgt es?"], ["Mennyi osztalékot kaphatok?", "How much dividend income could I receive?", "Wie viele Dividendeneinnahmen könnte ich erhalten?"], ["Mert jelezhet árfolyamesést, fenntarthatatlan kifizetést vagy magasabb üzleti kockázatot.", "Because it may signal a falling share price, an unsustainable payout or higher business risk.", "Denn sie kann auf fallende Kurse, eine nicht tragfähige Ausschüttung oder höhere Geschäftsrisiken hindeuten."], ["Mi az osztalék?", "What is a dividend?", "Was ist eine Dividende?"], ["Milyen gyakran fizetnek osztalékot?", "How often are dividends paid?", "Wie oft werden Dividenden gezahlt?"], ["Minden új befektetési év elején változtatja a havi befizetést.", "Changes the monthly contribution at the start of each new investment year.", "Ändert die monatliche Einzahlung zu Beginn jedes neuen Anlagejahres."], ["Mit jelent az osztalékhozam?", "What is dividend yield?", "Was bedeutet Dividendenrendite?"], ["Miért lehet veszélyes a túl magas osztalékhozam?", "Why can an unusually high dividend yield be risky?", "Warum kann eine ungewöhnlich hohe Dividendenrendite riskant sein?"], ["NAV aktuális személyijövedelemadó-tájékoztatói", "Current personal income tax guidance from NAV", "Aktuelle Informationen der NAV zur Einkommensteuer"], ["Negyedéves", "Quarterly", "Vierteljährlich"], ["Nem csökkenti a nominális eredményt; a mai vásárlóérték becsléséhez használjuk.", "It does not reduce the nominal result; it is used to estimate today's purchasing power.", "Sie mindert das nominale Ergebnis nicht, sondern dient zur Schätzung der heutigen Kaufkraft."], ["Nem. A vállalat csökkentheti, felfüggesztheti vagy megszüntetheti az osztalékot.", "No. A company may reduce, suspend or stop paying dividends.", "Nein. Ein Unternehmen kann Dividenden kürzen, aussetzen oder einstellen."], ["Nem. Ország, számlatípus, forrásadó, befektetési forma és egyéni helyzet alapján eltérhet, ezért a levonási arányt saját becslésként kell megadni.", "No. It varies by country, account type, withholding tax, investment type and personal circumstances, so enter your own estimated deduction rate.", "Nein. Sie variiert je nach Land, Kontotyp, Quellensteuer, Anlageform und persönlicher Situation. Gib deshalb eigene Schätzwerte für die Abzüge ein."], ["Nettó cél", "Net target", "Nettoziel"], ["Osztalék cashflow-ellenőrző", "Dividend cash-flow check", "Dividenden-Cashflow-Check"], ["Osztalék kezelése", "Dividend handling", "Dividendenbehandlung"], ["Osztalék és portfólió vizuális becslése", "Visual estimate of dividends and portfolio", "Visuelle Schätzung von Dividenden und Portfolio"], ["Osztalék újrabefektetése", "Dividend reinvestment", "Wiederanlage von Dividenden"], ["Osztalékbefektetésnél gyakori a devizás kitettség. Ha külföldi részvényeket, ETF-eket vagy több pénznemet kezelsz, érdemes előre átgondolni a devizaváltási és utalási költségeket is.", "Dividend investing often involves currency exposure. If you hold foreign shares, ETFs or multiple currencies, consider conversion and transfer costs in advance.", "Bei Dividendenanlagen besteht häufig ein Währungsrisiko. Wenn du ausländische Aktien, ETFs oder mehrere Währungen hältst, berücksichtige Wechsel- und Überweisungskosten vorab."], ["Osztalékbevétel tervezése", "Plan your dividend income", "Dividendeneinnahmen planen"], ["Osztalékjövedelem alakulása", "Dividend income over time", "Entwicklung der Dividendeneinnahmen"], ["Osztaléknövekedés, árfolyamváltozás és infláció", "Dividend growth, share-price changes and inflation", "Dividendenwachstum, Kursveränderungen und Inflation"], ["Osztaléktervező", "Dividend planner", "Dividendenplaner"], ["Osztalékvágás modellezése", "Model a dividend cut", "Dividendenkürzung modellieren"], ["Osztalékvágás stresszteszt", "Dividend-cut stress test", "Stresstest für Dividendenkürzungen"], ["Portfólió alakulása", "Portfolio growth", "Entwicklung des Portfolios"], ["Próbáld ki ugyanazt a portfóliót alacsonyabb osztalékhozammal és 20–30%-os egyszeri osztalékvágással is. Ha a terv csak optimista feltételezéssel működik, az fontosabb információ, mint a legszebb becsült havi összeg.", "Try the same portfolio with a lower dividend yield and a one-time 20–30% dividend cut. If the plan works only under optimistic assumptions, that matters more than the most attractive monthly estimate.", "Teste dasselbe Portfolio mit niedrigerer Dividendenrendite und einer einmaligen Kürzung um 20–30 %. Funktioniert der Plan nur mit optimistischen Annahmen, ist das wichtiger als der schönste geschätzte Monatsbetrag."], ["Például 30% osztalékvágás.", "For example, a 30% dividend cut.", "Zum Beispiel eine Dividendenkürzung um 30 %."], ["Rendszeres havi befektetés (Ft)", "Regular monthly investment (HUF)", "Regelmäßige monatliche Anlage (HUF)"], ["Részletes levonási mód", "Detailed deduction method", "Detaillierter Abzugsmodus"], ["Százalékos költség, amelyet a bruttó osztalékból vonunk le.", "A percentage-based fee deducted from gross dividends.", "Ein prozentualer Kostenanteil, der von der Bruttodividende abgezogen wird."], ["Teljes hozam", "Total return", "Gesamtrendite"], ["Teljes éves levonás", "Total annual deductions", "Jährliche Gesamtabzüge"], ["Tervezésnél érdemes a nettó becslést nézni, mert a levonások és költségek csökkenthetik a kézhez kapott összeget.", "For planning, look at the net estimate because deductions and costs can reduce the amount you receive.", "Für die Planung ist die Nettoschätzung sinnvoll, da Abzüge und Kosten den Auszahlungsbetrag mindern können."], ["További becsült adó (%)", "Additional estimated tax (%)", "Zusätzliche geschätzte Steuer (%)"], ["Tényleges nettó osztalékhozam", "Effective net dividend yield", "Effektive Nettodividendenrendite"], ["Wise bemutató", "Wise information", "Wise-Informationen"], ["az osztalék jogi fogalmának és adózási környezetének ellenőrzési alapja a", "the source for checking the legal definition of dividends and their tax framework is", "als Quelle zur Prüfung der rechtlichen Definition von Dividenden und ihres steuerlichen Rahmens dient"], ["az osztalék kalkulátor nem garantált passzív jövedelmet ígér, hanem megmutatja, hogy a hozam, a levonások, a kifizetési gyakoriság, az újrabefektetés és az infláció hogyan alakíthatja a becsült osztaléktervet.", "The dividend calculator does not promise guaranteed passive income. It shows how yield, deductions, payout frequency, reinvestment and inflation may shape an estimated dividend plan.", "Der Dividendenrechner verspricht kein garantiertes passives Einkommen. Er zeigt, wie Rendite, Abzüge, Auszahlungshäufigkeit, Wiederanlage und Inflation einen geschätzten Dividendenplan beeinflussen können."], ["pl. 100 000", "e.g. 100,000", "z. B. 100.000"], ["pl. 15", "e.g. 15", "z. B. 15"], ["pl. 20", "e.g. 20", "z. B. 20"], ["pl. 3 000 000", "e.g. 3,000,000", "z. B. 3.000.000"], ["pl. 4", "e.g. 4", "z. B. 4"], ["személyi jövedelemadóról szóló 1995. évi CXVII. törvény", "Act CXVII of 1995 on Personal Income Tax", "Gesetz CXVII von 1995 über die Einkommensteuer"], ["Érdemes újrabefektetni az osztalékot?", "Is reinvesting dividends worthwhile?", "Lohnt sich die Wiederanlage von Dividenden?"], ["Értékpapírtól függően havonta, negyedévente, félévente vagy évente, de a tényleges időpontok eltérhetnek.", "Depending on the security, payments may be monthly, quarterly, semi-annual or annual, but actual dates vary.", "Je nach Wertpapier erfolgen Zahlungen monatlich, vierteljährlich, halbjährlich oder jährlich; tatsächliche Termine können abweichen."], ["Év végi portfólióérték", "Portfolio value at year-end", "Portfoliowert zum Jahresende"], ["Éves becsült befizetés, portfólióérték, osztalék és reálérték", "Estimated annual contributions, portfolio value, dividends and real value", "Geschätzte jährliche Einzahlungen, Portfoliowert, Dividenden und Realwert"], ["Éves bruttó osztalék", "Annual gross dividends", "Jährliche Bruttodividende"], ["Éves bruttó osztalékhozam (%)", "Gross annual dividend yield (%)", "Jährliche Bruttodividendenrendite (%)"], ["Éves cél", "Annual target", "Jahresziel"], ["Éves fix költség (Ft)", "Annual fixed costs (HUF)", "Jährliche Fixkosten (HUF)"], ["Éves levonás és költség", "Annual deductions and costs", "Jährliche Abzüge und Kosten"], ["Éves nettó osztalék", "Annual net dividends", "Jährliche Nettodividende"], ["Éves osztaléknövekedés (%)", "Annual dividend growth (%)", "Jährliches Dividendenwachstum (%)"], ["Éves számla-, adat-, platform- vagy egyéb becsült fix költség.", "Estimated annual account, data, platform or other fixed costs.", "Geschätzte jährliche Konto-, Daten-, Plattform- oder sonstige Fixkosten."], ["Éves árfolyamváltozás (%)", "Annual price change (%)", "Jährliche Kursveränderung (%)"], ["Összes addigi nettó osztalék", "Cumulative net dividends to date", "Kumulierte Nettodividende bis heute"], ["Újrabefektetett osztalék", "Reinvested dividends", "Wiederangelegte Dividenden"],
    ["A megadott feltételek alapján a 3 M Ft forintos portfólió évente körülbelül 102 e Ft nettó osztalékot termelhet. Ez havi átlagban nagyjából 9 e Ft, negyedéves fizetés esetén pedig kifizetésenként körülbelül 26 e Ft.", "Under these assumptions, a HUF 3 million portfolio could generate about HUF 102,000 in net dividends per year. That averages around HUF 9,000 per month, or about HUF 26,000 per quarterly payment.", "Unter diesen Annahmen könnte ein Portfolio von 3 Mio. HUF jährlich etwa 102.000 HUF Nettodividenden erzielen. Das entspricht durchschnittlich rund 9.000 HUF im Monat oder etwa 26.000 HUF je vierteljährlicher Auszahlung."],
    ["Nem csökkenti a nominális eredményt; a mai vásárlóérték becsléséhez használjuk.", "It does not reduce the nominal result; it is used to estimate today's purchasing power.", "Sie mindert das nominale Ergebnis nicht, sondern dient zur Schätzung der heutigen Kaufkraft."],
    ["Az osztalékból becsült elsődleges levonás.", "Estimated primary deduction from dividends.", "Geschätzter Hauptabzug von der Dividende."],
    ["A százalékos levonások összege nem haladhatja meg a 100%-ot.", "Percentage deductions cannot total more than 100%.", "Die prozentualen Abzüge dürfen zusammen 100 % nicht überschreiten."],
    ["A százalékos levonások összege nem haladhatja meg a 100%-ot.", "Percentage deductions cannot total more than 100%.", "Die prozentualen Abzüge dürfen zusammen 100 % nicht überschreiten."],
    ["A megadott feltételek alapján a havi nettó célhoz körülbelül ${capital} portfólióra lehet szükség.", "Based on the assumptions provided, about ${capital} in portfolio capital may be needed for the monthly net target.", "Auf Grundlage deiner Angaben könnten etwa ${capital} Portfoliokapital für das monatliche Nettoziel erforderlich sein."],
    ["Adj meg értelmezhető adatokat, és a kalkulátor megmutatja a becsült eredményt.", "Enter valid values to see the estimated result.", "Gib gültige Werte ein, um das geschätzte Ergebnis zu sehen."],
    ["Adj meg adatokat az éves bontáshoz.", "Enter values to see the annual breakdown.", "Gib Werte ein, um die Jahresübersicht zu sehen."],
    ["Az osztalékhozam legyen 0% és 100% között.", "Dividend yield must be between 0% and 100%.", "Die Dividendenrendite muss zwischen 0 % und 100 % liegen."], ["A levonás legyen 0% és 100% között.", "Deductions must be between 0% and 100%.", "Die Abzüge müssen zwischen 0 % und 100 % liegen."], ["Az osztaléknövekedés legyen -100% és 100% között.", "Dividend growth must be between -100% and 100%.", "Das Dividendenwachstum muss zwischen -100 % und 100 % liegen."], ["Az árfolyamváltozás legyen nagyobb mint -100% és legfeljebb 100% között.", "Price change must be greater than -100% and no more than 100%.", "Die Kursveränderung muss über -100 % und höchstens 100 % liegen."], ["Az infláció legyen -20% és 100% között.", "Inflation must be between -20% and 100%.", "Die Inflation muss zwischen -20 % und 100 % liegen."], ["A befizetésemelés legyen -100% és 100% között.", "Contribution increases must be between -100% and 100%.", "Die Erhöhung der Einzahlungen muss zwischen -100 % und 100 % liegen."], ["Az osztalékvágás legyen 0% és 100% között.", "The dividend cut must be between 0% and 100%.", "Die Dividendenkürzung muss zwischen 0 % und 100 % liegen."], ["Adj meg kezdő portfóliót vagy havi befektetést.", "Enter a starting portfolio or a monthly investment.", "Gib ein Startportfolio oder eine monatliche Anlage ein."],
    ["A már meglévő osztaléktermelő befektetés becsült értéke.", "Estimated value of your existing dividend-paying investments.", "Geschätzter Wert deiner bestehenden Dividendenanlagen."],
    ["A havi összeg éves átlag; a tényleges kifizetési időpontok ettől eltérhetnek.", "The monthly amount is an annual average; actual payment dates may differ.", "Der Monatsbetrag ist ein Jahresdurchschnitt; tatsächliche Auszahlungstermine können abweichen."],
    ["Szükséges portfólióméret", "Required portfolio size", "Erforderliche Portfoliogröße"], ["Várható portfólióérték", "Projected portfolio value", "Voraussichtlicher Portfoliowert"], ["Teljes saját befizetés", "Total contributions", "Gesamte Einzahlungen"], ["Összes nettó osztalék", "Total net dividends", "Nettodividenden insgesamt"], ["Utolsó év becsült éves nettó osztaléka", "Estimated annual net dividends in the final year", "Geschätzte jährliche Nettodividende im letzten Jahr"], ["Utolsó év havi nettó átlaga", "Average monthly net income in the final year", "Durchschnittliche monatliche Nettoeinnahmen im letzten Jahr"], ["Mai vásárlóértékű portfólió", "Portfolio in today's money", "Portfoliowert in heutiger Kaufkraft"], ["Mai vásárlóértékű éves osztalék", "Annual dividends in today's money", "Jährliche Dividende in heutiger Kaufkraft"], ["Saját befizetésre vetített osztalékhozam", "Dividend yield on contributions", "Dividendenrendite auf die Einzahlungen"], ["Éves bruttó, nettó és levonások", "Annual gross dividends, net dividends and deductions", "Jährliche Brutto- und Nettodividenden sowie Abzüge"], ["Szükséges tőke hozamfeltételezések szerint", "Capital required under different yield assumptions", "Erforderliches Kapital bei unterschiedlichen Renditeannahmen"], ["Mai vásárlóértékű nettó osztalék", "Net dividends in today's money", "Nettodividende in heutiger Kaufkraft"], ["Saját befizetés", "Contributions", "Einzahlungen"], ["Portfólióérték", "Portfolio value", "Portfoliowert"], ["Teljes levonás", "Total deductions", "Gesamtabzüge"], ["Nem számítható", "Cannot be calculated", "Nicht berechenbar"],
    ["Adj meg egy összeget.", "Enter an amount.", "Gib einen Betrag ein."], ["Csak számot adj meg, szóközzel vagy tizedesvesszővel is írhatod.", "Enter a number; spaces and a decimal comma are also accepted.", "Gib eine Zahl ein; Leerzeichen und Dezimalkomma sind ebenfalls zulässig."], ["Az összeg nem lehet negatív.", "The amount cannot be negative.", "Der Betrag darf nicht negativ sein."], ["Adj meg 0-nál nagyobb összeget.", "Enter an amount greater than zero.", "Gib einen Betrag über null ein."], ["Ez az összeg túl nagy a megbízható becsléshez.", "This amount is too large for a reliable estimate.", "Dieser Betrag ist für eine zuverlässige Schätzung zu hoch."], ["Adj meg egy százalékos értéket.", "Enter a percentage.", "Gib einen Prozentwert ein."], ["Csak számot adj meg, például 4 vagy 0,20 formában.", "Enter a number, for example 4 or 0.20.", "Gib eine Zahl ein, zum Beispiel 4 oder 0,20."], ["Add meg az időtávot években.", "Enter the time horizon in years.", "Gib den Anlagezeitraum in Jahren ein."], ["Az időtáv csak szám lehet.", "The time horizon must be a number.", "Der Anlagezeitraum muss eine Zahl sein."],
    ["A megadott levonások és költségek felemésztik a becsült bruttó osztalékot.", "The deductions and costs entered consume the estimated gross dividends.", "Die eingegebenen Abzüge und Kosten zehren die geschätzte Bruttodividende auf."], ["A megadott osztalékhozam mellett a céljövedelem nem számítható ki. Adj meg 0%-nál magasabb osztalékhozamot.", "The income target cannot be calculated at this dividend yield. Enter a yield above 0%.", "Bei dieser Dividendenrendite lässt sich das Einkommensziel nicht berechnen. Gib eine Rendite über 0 % ein."], ["A megadott hozam, levonások és költségek mellett a céljövedelem nem számítható ki. Csökkentsd a levonásokat vagy adj meg magasabb osztalékhozamot.", "The income target cannot be calculated with this yield, deductions and costs. Reduce deductions or enter a higher dividend yield.", "Mit dieser Rendite, diesen Abzügen und Kosten lässt sich das Einkommensziel nicht berechnen. Verringere die Abzüge oder gib eine höhere Rendite ein."], ["A céljövedelemhez szükséges tőke túl nagy vagy nem számítható megbízhatóan.", "The capital required for this income target is too large or cannot be estimated reliably.", "Das für dieses Einkommensziel erforderliche Kapital ist zu hoch oder lässt sich nicht zuverlässig schätzen."], ["A százalékos levonások összege nem haladhatja meg a 100%-ot.", "The total percentage deductions cannot exceed 100%.", "Die prozentualen Abzüge dürfen insgesamt 100 % nicht überschreiten."], ["Teljes levonás:", "Total deductions:", "Gesamtabzüge:"], ["Stresszteszt nélkül az utolsó év becsült nettó osztaléka", "Without the stress test, estimated net dividends in the final year are", "Ohne Stresstest beträgt die geschätzte Nettodividende im letzten Jahr"],
    ["Alacsonyabb hozam", "Lower yield", "Niedrigere Rendite"], ["Alapfeltételezés", "Base assumption", "Basisannahme"], ["Az eredmény után", "After your result", "Nach deinem Ergebnis"],
    ["Az osztalékhozam nem garantált, ezért a céljövedelmet érdemes hosszabb távú növekedési és inflációs forgatókönyvvel is összevetni.", "Dividend yield is not guaranteed, so compare your income target with longer-term growth and inflation scenarios too.", "Die Dividendenrendite ist nicht garantiert. Vergleiche dein Einkommensziel daher auch mit langfristigen Wachstums- und Inflationsszenarien."],
    ["Az éves bontás a hosszú távú módban érhető el.", "The annual breakdown is available in long-term mode.", "Die Jahresübersicht ist im Langzeitmodus verfügbar."], ["Bruttó", "Gross", "Brutto"], ["Ellenőrizd a szükséges tőkét más szemszögből is", "Check the required capital from another angle", "Prüfe den Kapitalbedarf aus einer anderen Perspektive"], ["Hasonlítsd össze a teljes hozamra épülő megközelítéssel.", "Compare it with an approach based on total return.", "Vergleiche es mit einem Ansatz, der auf der Gesamtrendite basiert."], ["Hirdetés", "Advertisement", "Anzeige"], ["Infláció", "Inflation", "Inflation"], ["Levonás", "Deduction", "Abzug"], ["Magasabb hozam", "Higher yield", "Höhere Rendite"], ["Nettó", "Net", "Netto"], ["Vizsgáld meg a céljövedelem jövőbeli vásárlóerejét.", "Explore the future purchasing power of your target income.", "Prüfe die künftige Kaufkraft deines Einkommensziels."],
  ];
  const pages = ["osztalek-kalkulator"];
  const supported = ["hu", "en", "de"];
  const rows = [...commonRows, ...ownRows];
  const dictionaries = Object.freeze({ [pages[0]]: Object.freeze(Object.fromEntries(rows.map(([source, en, de]) => [source, Object.freeze([en, de])]))) });
  const lookup = new Map(rows.map(row => [row[0], row]));
  function translate(page, text, lang) {
    if (!pages.includes(page) || !supported.includes(lang) || lang === "hu") return null;
    const row = lookup.get(text);
    if (row) return row[supported.indexOf(lang)];
    const money = /^(\d[\d\s.,\u00a0]*?)\s*Ft$/u.exec(text);
    if (money) return `${money[1]} HUF`;
    const compactMoney = /^(\d+(?:[,.]\d+)?)\s*(M|e) Ft$/u.exec(text);
    if (compactMoney) {
      const amount = compactMoney[1].replace(",", ".");
      if (compactMoney[2] === "M") return lang === "en" ? `HUF ${amount}m` : `${amount.replace(".", ",")} Mio. HUF`;
      return lang === "en" ? `HUF ${amount}k` : `${amount.replace(".", ",")} Tsd. HUF`;
    }
    const yieldLabel = /^(\d+(?:[,.]\d+)?)% bruttó osztalékhozam$/u.exec(text);
    if (yieldLabel) return lang === "en" ? `${yieldLabel[1]}% gross dividend yield` : `${yieldLabel[1].replace(".", ",")} % Bruttodividendenrendite`;
    const income = /^A megadott feltételek alapján a (.+?) forintos portfólió évente körülbelül (.+?) nettó osztalékot termelhet\. Ez havi átlagban nagyjából (.+?), (.+?) fizetés esetén pedig kifizetésenként körülbelül (.+?)\.$/u.exec(text);
    if (income) {
      const amounts = [income[1], income[2], income[3], income[5]].map(value => translate(page, value, lang) ?? value);
      const frequencies = { havi: ["monthly", "monatlich"], negyedéves: ["quarterly", "vierteljährlicher"], féléves: ["semi-annual", "halbjährlicher"], éves: ["annual", "jährlicher"], monthly: ["monthly", "monatlich"], quarterly: ["quarterly", "vierteljährlicher"], "semi-annual": ["semi-annual", "halbjährlicher"], annual: ["annual", "jährlicher"], monatlich: ["monthly", "monatlich"], vierteljährlich: ["quarterly", "vierteljährlicher"], halbjährlich: ["semi-annual", "halbjährlicher"], jährlich: ["annual", "jährlicher"] };
      const frequency = frequencies[income[4]]?.[supported.indexOf(lang) - 1] ?? income[4];
      return lang === "en"
        ? `Based on your assumptions, a ${amounts[0]} portfolio could generate about ${amounts[1]} in net dividends per year. That averages around ${amounts[2]} per month, or about ${amounts[3]} per ${frequency} payment.`
        : `Nach deinen Angaben könnte ein Portfolio von ${amounts[0]} jährlich etwa ${amounts[1]} Nettodividenden erzielen. Das entspricht durchschnittlich rund ${amounts[2]} im Monat oder etwa ${amounts[3]} je ${frequency} Auszahlung.`;
    }
    const target = /^A megadott feltételek alapján a (havi|éves) (nettó|bruttó) céljövedelemhez körülbelül (.+?) portfólióra lehet szükség\. A felfelé kerekített tőkével számolt éves nettó osztalék becslés szerint (.+?)\.$/u.exec(text);
    if (target) {
      const capital = translate(page, target[3], lang) ?? target[3];
      const annual = translate(page, target[4], lang) ?? target[4];
      const targetName = lang === "en" ? `${target[1] === "havi" ? "monthly" : "annual"} ${target[2]}` : `${target[1] === "havi" ? "monatliches" : "jährliches"} ${target[2] === "nettó" ? "Nettoziel" : "Bruttoziel"}`;
      return lang === "en" ? `Based on your assumptions, a portfolio of about ${capital} may be needed for a ${targetName} income target. With rounded-up capital, estimated annual net dividends would be ${annual}.` : `Nach deinen Angaben könnte ein Portfolio von etwa ${capital} für ein ${targetName} erforderlich sein. Mit aufgerundetem Kapital läge die geschätzte jährliche Nettodividende bei ${annual}.`;
    }
    const projection = /^A megadott feltételek alapján (\d+) év végére a portfólió körülbelül (.+?) értéket érhet el\. Újrabefektetéssel a portfólió becsült értéke (.+?), az éves nettó osztalék pedig (.+?) összeggel lehetne magasabb ugyanilyen feltételek mellett\.(.*)$/u.exec(text);
    if (projection) {
      const amount = value => translate(page, value, lang) ?? value;
      const stress = /^ Stresszteszt nélkül az utolsó év becsült nettó osztaléka (.+?), a stressztesztben (.+?)\.$/u.exec(projection[5]);
      const stressCopy = stress ? (lang === "en" ? ` Without the stress test, estimated net dividends in the final year would be ${amount(stress[1])}; under the stress test, they would be ${amount(stress[2])}.` : `Ohne Stresstest läge die geschätzte Nettodividende im letzten Jahr bei ${amount(stress[1])}, im Stresstest bei ${amount(stress[2])}.`) : "";
      return lang === "en" ? `Based on your assumptions, the portfolio could be worth about ${amount(projection[2])} after ${projection[1]} years. Reinvesting dividends could make the estimated portfolio value ${amount(projection[3])} higher and annual net dividends ${amount(projection[4])} higher under the same assumptions.${stressCopy}` : `Nach deinen Angaben könnte das Portfolio nach ${projection[1]} Jahren etwa ${amount(projection[2])} wert sein. Durch die Wiederanlage könnten der geschätzte Portfoliowert um ${amount(projection[3])} und die jährliche Nettodividende unter denselben Annahmen um ${amount(projection[4])} höher liegen.${stressCopy}`;
    }
    const annualDividend = /^Éves nettó osztalék: (.+)$/u.exec(text);
    if (annualDividend) return `${lang === "en" ? "Annual net dividends" : "Jährliche Nettodividende"}: ${translate(page, annualDividend[1], lang) ?? annualDividend[1]}`;
    const amountLabel = /^(Teljes levonás|Éves bruttó osztalék): (.+?) Ft$/u.exec(text);
    if (amountLabel) {
      const label = amountLabel[1] === "Teljes levonás"
        ? (lang === "en" ? "Total deductions" : "Gesamtabzüge")
        : (lang === "en" ? "Annual gross dividends" : "Jährliche Bruttodividende");
      const amount = translate(page, amountLabel[2] + " Ft", lang) ?? amountLabel[2] + " HUF";
      return `${label}: ${amount}`;
    }
    const year = /^(\d+)\. év$/u.exec(text);
    if (year) return lang === "en" ? `Year ${year[1]}` : `${year[1]}. Jahr`;
    const invalidPercent = /^Az érték legyen (.+)% és (.+)% között\.$/u.exec(text);
    if (invalidPercent) return lang === "en" ? `The value must be between ${invalidPercent[1]}% and ${invalidPercent[2]}%.` : `Der Wert muss zwischen ${invalidPercent[1]} % und ${invalidPercent[2]} % liegen.`;
    const invalidYears = /^Az időtáv legyen (\d+) és (\d+) év között\.$/u.exec(text);
    if (invalidYears) return lang === "en" ? `The time horizon must be between ${invalidYears[1]} and ${invalidYears[2]} years.` : `Der Anlagezeitraum muss zwischen ${invalidYears[1]} und ${invalidYears[2]} Jahren liegen.`;
    return null;
  }
  return Object.freeze({ pages, supported, dictionaries, translate });
});
